<?php

declare(strict_types=1);

namespace App\Lsp\Features\Eloquent;

use App\Lsp\Project;
use App\Lsp\Support\PhpMembers;
use App\Lsp\Support\WorkspaceIndex;

/**
 * Where an Eloquent attribute is written down.
 *
 * A column has no declaration in PHP. The closest thing is the `@property` line of the
 * model's docblock, most often generated by ide-helper into the mixin class the model
 * points to. That line is where a click on `$model->attribute` already lands, so it is
 * where a click on the same name written as a string lands too.
 */
class AttributeDeclarations
{
    /**
     * The declarations already found, keyed by class and attribute.
     *
     * @var array<string, array{path: string, line: int}|null>
     */
    protected array $found = [];

    /**
     * Create a new attribute declarations instance.
     */
    public function __construct(
        protected Project $project,
        protected WorkspaceIndex $index,
        protected PhpMembers $members,
    ) {}

    /**
     * Find where the given attribute of the given model is declared.
     *
     * The path is relative to the workspace and the line is 1-based, the form a link
     * target takes.
     *
     * @param  array<string, mixed>  $model
     * @return array{path: string, line: int}|null
     */
    public function find(array $model, string $attribute): ?array
    {
        $class = (string) ($model['class'] ?? '');

        if (array_key_exists("{$class}::{$attribute}", $this->found)) {
            return $this->found["{$class}::{$attribute}"];
        }

        return $this->found["{$class}::{$attribute}"] = $this->search($model, $attribute);
    }

    /**
     * Search where the given attribute of the given model is declared.
     *
     * @param  array<string, mixed>  $model
     * @return array{path: string, line: int}|null
     */
    protected function search(array $model, string $attribute): ?array
    {
        $path = (string) ($model['path'] ?? '');
        $class = (string) ($model['class'] ?? '');

        if ($path === '' || $class === '') {
            return null;
        }

        $source = $this->index->files()[$this->project->path($path)] ?? null;

        if ($source === null) {
            return null;
        }

        $docblock = $this->docblockOf($source, $class);

        $line = $this->propertyLine($docblock, $attribute);

        if ($line !== null) {
            return ['path' => $path, 'line' => $line];
        }

        foreach ($this->mixinsOf($docblock, $source, $class) as $mixin) {
            $declaration = $this->members->findDeclaration($mixin);

            if ($declaration === null) {
                continue;
            }

            $line = $this->propertyLine($this->docblockOf($declaration['source'], $mixin), $attribute);

            if ($line !== null) {
                return [
                    'path' => $this->project->uri()->relativePath($declaration['path']),
                    'line' => $line,
                ];
            }
        }

        return ['path' => $path, 'line' => $this->classLine($source, $class)];
    }

    /**
     * Get the docblock written above the given class, keyed by 1-based line.
     *
     * @return array<int, string>
     */
    protected function docblockOf(string $source, string $class): array
    {
        $lines = explode("\n", $source);
        $index = $this->classLine($source, $class) - 2;

        // Attributes and blank lines may sit between the docblock and the class.
        while ($index >= 0 && (trim($lines[$index]) === '' || str_starts_with(trim($lines[$index]), '#['))) {
            $index--;
        }

        if ($index < 0 || !str_ends_with(trim($lines[$index]), '*/')) {
            return [];
        }

        $docblock = [];

        for (; $index >= 0; $index--) {
            $docblock[$index + 1] = $lines[$index];

            if (str_starts_with(trim($lines[$index]), '/**')) {
                return array_reverse($docblock, true);
            }
        }

        return [];
    }

    /**
     * Get the 1-based line declaring the given class, or the first line.
     */
    protected function classLine(string $source, string $class): int
    {
        $shortName = preg_quote($this->shortName($class), '/');

        if (preg_match('/^[ \t]*(?:(?:final|abstract|readonly)\s+)*class\s+' . $shortName . '\b/m', $source, $found, PREG_OFFSET_CAPTURE) !== 1) {
            return 1;
        }

        return substr_count($source, "\n", 0, $found[0][1]) + 1;
    }

    /**
     * Get the line of the docblock declaring the given property, if it declares it.
     *
     * @param  array<int, string>  $docblock
     */
    protected function propertyLine(array $docblock, string $attribute): ?int
    {
        $property = '/@property(?:-read|-write)?\b.*\$' . preg_quote($attribute, '/') . '\b/';

        foreach ($docblock as $line => $text) {
            if (preg_match($property, $text) === 1) {
                return $line;
            }
        }

        return null;
    }

    /**
     * Get the classes the docblock mixes in, fully qualified.
     *
     * @param  array<int, string>  $docblock
     * @return array<int, string>
     */
    protected function mixinsOf(array $docblock, string $source, string $class): array
    {
        $mixins = [];

        foreach ($docblock as $text) {
            if (preg_match('/@mixin\s+([\w\\\\]+)/', $text, $found) === 1) {
                $mixins[] = $this->qualify($found[1], $source, $class);
            }
        }

        return $mixins;
    }

    /**
     * Resolve a name written in the given class to its fully qualified form.
     */
    protected function qualify(string $name, string $source, string $class): string
    {
        if (str_starts_with($name, '\\')) {
            return ltrim($name, '\\');
        }

        $head = explode('\\', $name)[0];

        preg_match_all('/^use\s+([\w\\\\]+)(?:\s+as\s+(\w+))?\s*;/m', $source, $imports, PREG_SET_ORDER);

        foreach ($imports as $import) {
            $alias = ($import[2] ?? '') !== '' ? $import[2] : $this->shortName($import[1]);

            if ($alias === $head) {
                return $import[1] . substr($name, strlen($head));
            }
        }

        $namespace = substr($class, 0, (int) strrpos($class, '\\'));

        return $namespace === '' ? $name : $namespace . '\\' . $name;
    }

    /**
     * Get the unqualified name of the given class.
     */
    protected function shortName(string $class): string
    {
        $position = strrpos($class, '\\');

        return $position === false ? $class : substr($class, $position + 1);
    }
}
